// <nonce_check>
// Nonce WeakMap
//
// Tracks per-render nonces from precompile scripts. We reject expression
// invocations on elements whose data-ds-nonce does not match the nonce
// associated with their nearest nonce-tagged ancestor. This is primarily a
// protection against server-side injection (handling the case where an
// attacker has injected an existing precompiled attribute), but it also adds
// an additional layer of protection against client-side injection.
//
// nonceMap keys are either document.documentElement (seeded with the initial
// page nonce), the root of each patch-inserted subtree, or a patch-morphed
// element whose data-ds-nonce changes. At invocation time, checked() walks up
// the ancestor chain to find the nearest key and compares its nonce against
// the element's data-ds-nonce.
//
// To make repeated checks faster, we add a redundant entry to the WeakMap for
// the 5th ancestor the node we're walking from.
let nonceCheckActive = false;
let currentPatchNonce = null; // set during each patch window for the MutationObserver
const nonceMap = new WeakMap();

// The page nonce arrives in a Server-Timing response header rather than in
// the DOM, so CSS attribute-selector exfiltration can't read it. serverTiming
// is only populated in secure contexts (HTTPS or localhost); elsewhere the
// nonce check stays inactive.
const pageNonce = performance
  .getEntriesByType("navigation")[0]
  ?.serverTiming?.find(
    (t) => t.name === "datastargostrictcsp-ds-nonce",
  )?.description;
if (pageNonce) {
  nonceMap.set(document.documentElement, pageNonce);
  nonceCheckActive = true;
}
// </nonce_check>

// Blessed/cursed element registry
//
// document.documentElement is the single blessed seed — all initial DOM nodes
// inherit blessing by walking up to it. When the MutationObserver fires, the
// root of each inserted subtree is marked as cursed if it is not inserted
// via a legitimate Datastar patching operation. The isBlessed function walks
// up the ancestor chain, looking for either a blessed or a cursed ancestor.
// To make repeated checks faster, we add the 5th ancestor of a
// blessed/cursed node to the registry after the initial walk to the
// blessed/cursed ancestor.
//
// This protection is complementary to the nonce check: the nonce check is
// opt-in; the blessing check is always active.
const blessing = new WeakMap();
let blessingEnabled = false;

blessing.set(document.documentElement, true);

const mo = new MutationObserver((records) => {
  for (const r of records) {
    if (r.type === "childList") {
      for (const node of r.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;
        if (!blessingEnabled) {
          blessing.set(node, false);
        }
        // <nonce_check>
        if (currentPatchNonce !== null) {
          nonceMap.set(node, currentPatchNonce);
        }
        // </nonce_check>
      }
    }
    // <nonce_check>
    if (
      currentPatchNonce !== null &&
      r.type === "attributes" &&
      r.attributeName === "data-ds-nonce" &&
      r.target.nodeType === Node.ELEMENT_NODE
    ) {
      nonceMap.set(r.target, currentPatchNonce);
    }
    // </nonce_check>
  }
});
const observeOptions = {
  childList: true,
  subtree: true,
  // <nonce_check>
  attributes: true,
  attributeFilter: ["data-ds-nonce"],
  // </nonce_check>
};
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () =>
    mo.observe(document.documentElement, observeOptions),
  );
} else {
  mo.observe(document.documentElement, observeOptions);
}

function isBlessed(el) {
  let node = el;
  let steps = 0;
  let midpoint = null;
  while (node && node.nodeType === Node.ELEMENT_NODE) {
    if (steps === 5) midpoint = node;
    if (blessing.has(node)) {
      const value = blessing.get(node);
      // Two situations to think about here:
      //   (i)  A cursed node later gets added *within* midpoint. In that case, the walk from that node will reach the cursed node first.
      //   (ii) A cursed node later gets added *above* midpoint. In that case, midpoint will have been replaced with a new subtree, so won't be visited on the walk.
      if (midpoint) blessing.set(midpoint, value);
      return value;
    }
    node = node.parentElement;
    steps++;
  }
  return false;
}

// <nonce_check>
function hasValidNonce(el) {
  let node = el;
  let steps = 0;
  let midpoint = null;
  while (node) {
    if (steps === 5) midpoint = node;
    if (nonceMap.has(node)) {
      const expected = nonceMap.get(node);
      if (midpoint) nonceMap.set(midpoint, expected);
      return el?.dataset?.dsNonce === expected;
    }
    node = node.parentElement;
    steps++;
  }
  return false;
}
// </nonce_check>

// Wrap fn so blessing and nonce checks run at invocation time (when el is available).
function checked(fn) {
  return function (el) {
    // <nonce_check>
    if (nonceCheckActive && !hasValidNonce(el)) {
      console.error(
        "[datastarstrictcsp] nonce check failed: expression blocked on element:",
        el,
      );
      return;
    }
    // </nonce_check>
    if (!isBlessed(el)) {
      console.error(
        "[datastarstrictcsp] element not blessed: expression blocked on element:",
        el,
      );
      return;
    }
    return fn.apply(this, arguments);
  };
}

// Function proxy
//
// Intercepts new Function(...) calls so Datastar uses precompiled functions
// from window.__datastar_precompiled_expressions instead of eval-ing expressions at runtime.
const _Function = Function;
// Preserve any entries already registered by precompile scripts that ran
// before this module (possible when they are injected earlier in <head>).
const p = (window.__datastar_precompiled_expressions ??= new Map());

function proxyHandler(args) {
  const fn = p.get(JSON.stringify(args));
  return fn ? checked(fn) : new _Function(...args);
}
window.Function = new Proxy(_Function, {
  apply: (_t, _th, args) => proxyHandler(args),
  construct: (_t, args) => proxyHandler(args),
});

// Precompile interceptor
//
// Datastar dispatches a datastar-fetch CustomEvent before applying any patch.
// We intercept datastar-patch-elements events that carry a precompile signal —
// either argsRaw.precompileUrl (SSE path, added as a data: field) or an HTML
// comment at the top of argsRaw.elements (text/html path, added by Middleware).
// We load the precompile script(s), then re-dispatch the cleaned event so
// Datastar applies the patch with all expressions already registered.
//
// Our listener is registered before Datastar's, so stopImmediatePropagation
// prevents Datastar from seeing the original event.
const loadedScripts = new Set();

function loadScript(url) {
  const key = url.slice(url.lastIndexOf("&sig=") + 5);
  if (loadedScripts.has(key)) return Promise.resolve();
  loadedScripts.add(key);
  return new Promise((resolve) => {
    const s = document.createElement("script");
    s.src = url;
    s.type = "module";
    s.onload = s.onerror = () => {
      s.remove();
      resolve();
    }; // fail open: patch proceeds even if script 404s
    document.head.appendChild(s);
  });
}

// Matches <!-- [ds-nonce: NONCE] [precompile-url: URL] --> (capture 1: nonce, capture 2: URL).
// Both parts are optional but at least one must be present (checked in code).
const COMMENT_RE =
  /^<!--\s*(?:ds-nonce:\s*(\S+))?\s*(?:precompile-url:\s*(\S+))?\s*-->\n?/;

document.addEventListener("datastar-fetch", (evt) => {
  if (evt.detail.type !== "datastar-patch-elements") return;
  const argsRaw = evt.detail.argsRaw;

  // <nonce_check>
  let patchNonce = null;
  // </nonce_check>

  let urls = null;
  if (argsRaw.precompileUrl) {
    // SSE path: precompile URLs in a data: precompileUrl field.
    urls = argsRaw.precompileUrl.split(" ");
    delete argsRaw.precompileUrl;
    // <nonce_check>
    if (argsRaw.dsNonce) {
      patchNonce = argsRaw.dsNonce;
      delete argsRaw.dsNonce;
    }
    // </nonce_check>
  } else if (argsRaw.elements) {
    // text/html path: one comment per URL (nonce on the first), consume all.
    urls = [];
    let rest = argsRaw.elements;
    for (let m; (m = rest.match(COMMENT_RE)) && (m[1] ?? m[2]); ) {
      // <nonce_check>
      if (m[1]) patchNonce = m[1];
      // </nonce_check>
      if (m[2]) urls.push(m[2]);
      rest = rest.slice(m[0].length);
    }
    argsRaw.elements = rest;
    if (!urls.length) urls = null;
  }

  if (!urls) return;

  evt.stopImmediatePropagation();

  Promise.all(urls.map(loadScript)).then(() => {
    // <nonce_check>
    currentPatchNonce = patchNonce;
    // </nonce_check>
    blessingEnabled = true;
    document.dispatchEvent(
      new CustomEvent("datastar-fetch", {
        detail: evt.detail,
      }),
    );
    // MutationObserver callbacks are microtasks; setTimeout (macrotask)
    // fires after them, so newly patched elements are blessed before we
    // close the window.
    setTimeout(() => {
      blessingEnabled = false;
      // <nonce_check>
      currentPatchNonce = null;
      // </nonce_check>
    }, 0);
  });
});
